def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj):
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        if isinstance(obj, dict):
            if "position" in obj:
                return pos(obj.get("position"))
            return obj.get("x", 0), obj.get("y", 0)
        return 0, 0

    def get_pos(key, default=(0, 0)):
        return pos(observation.get(key, default))

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets or []:
            tx, ty = pos(t)
            d = abs(tx - sx) + abs(ty - sy)
            if best is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    def steer(tx, ty, sx, sy):
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    env = observation.get("environment_name") or observation.get("env") or ""
    sx, sy = get_pos("self_position", observation.get("self", (0, 0)))
    ox, oy = get_pos("opponent_position", observation.get("opponent", (sx, sy)))
    gw = observation.get("grid_width") or observation.get("width") or 0
    gh = observation.get("grid_height") or observation.get("height") or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role") or observation.get("role") or "pursuer"
        if role == "pursuer":
            return steer(ox, oy, sx, sy)
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(sx - 1, sy - 1), (sx - 1, sy + 1), (sx + 1, sy - 1), (sx + 1, sy + 1)]
        target = None
        best_d = None
        for cx, cy in corners:
            d = abs(cx - ox) + abs(cy - oy)
            if target is None or d > best_d:
                target = (cx, cy)
                best_d = d
        return steer(target[0], target[1], sx, sy)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier")
            or observation.get("targets")
            or []
        )
        if targets:
            best = nearest(targets, sx, sy)
            if best is not None:
                return steer(best[0], best[1], sx, sy)
        if gw and gh:
            cx = gw // 2
            cy = gh // 2
            return steer(cx, cy, sx, sy)
        return [0, 0]

    resources = (
        observation.get("resources")
        or observation.get("resource_positions")
        or observation.get("items")
        or []
    )
    if resources:
        best = nearest(resources, sx, sy)
        if best is not None:
            return steer(best[0], best[1], sx, sy)

    if ox != sx or oy != sy:
        return steer(ox, oy, sx, sy)
    return [0, 0]

